/// فقط نام استان‌ها، برای سلکت یا کمبوباکس.
final List<String> provinceNames = provinces.map((p) => p.name).toList();

/// شهرهای یک استان (مرکز اول)؛ برای استان ناشناخته لیست خالی.
List<String> citiesOf(String province) {
  for (final p in provinces) {
    if (p.name == province) return p.cities;
  }
  return const [];
}

/// تک‌تک استان‌هایی که شهری با این نام دارند (چند نام مثل «حاجی‌آباد» تکراری است).
List<String> provincesOf(String city) => [
      for (final p in provinces)
        if (p.cities.contains(city)) p.name,
    ];

/// آیا این جفت استان/شهر در دیتاست هست؟
bool isValidAddress(String province, String city) => citiesOf(province).contains(city);
